package com.saivandan.crm.api;
import com.saivandan.crm.domain.*; import com.saivandan.crm.repo.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/follow-ups") public class FollowUpController { private final FollowUpRepository followUps; private final LeadRepository leads; public FollowUpController(FollowUpRepository f,LeadRepository l){followUps=f;leads=l;} @GetMapping public List<FollowUp> list(){return followUps.findAllByOrderByScheduledAtAsc();} @PostMapping public ResponseEntity<FollowUp> create(@Valid @RequestBody Request r){Lead l=leads.findById(r.leadId()).orElseThrow();return ResponseEntity.status(HttpStatus.CREATED).body(followUps.save(new FollowUp(l,r.type(),r.scheduledAt(),r.remarks(),r.executive())));} public record Request(@NotNull Long leadId,@NotBlank String type,@NotNull LocalDateTime scheduledAt,String remarks,String executive){} }
